mapper.select:
SELECT ID, USER_CODE, USER_ID, USER_PW, USER_NAME, ROLE_GROUP
  FROM AUTH_USER
 WHERE USER_ID = #{userId}

SELECT ID, USER_CODE, USER_ID, USER_PW, USER_NAME, ROLE_GROUP
  FROM AUTH_USER
 WHERE USER_CODE = #{userCode}

SELECT EXISTS (
    SELECT 1
      FROM AUTH_USER
     WHERE USER_ID = #{userId}
)

mapper.insert:
INSERT INTO AUTH_USER (
    USER_CODE, USER_ID, USER_PW, USER_NAME, ROLE_GROUP
) VALUES (
    #{userCode}, #{userId}, #{userPw}, #{userName}, #{roleGroup}
)
